problems.solution:
def rrf(rankings, c=60):
    scores = {}
    for ranking in rankings:
        for rank, doc in enumerate(ranking, start=1):
            scores[doc] = scores.get(doc, 0) + 1 / (c + rank)
    return sorted(scores, key=lambda d: (-scores[d], d))
